abstract class DatabaseRecord {
    protected final String recordId;
    protected final long createdAt;

    // Abstract class constructor enforcing invariants
    public DatabaseRecord(String recordId) {
        if (recordId == null || recordId.trim().isEmpty()) {
            throw new IllegalArgumentException("recordId cannot be null or blank");
        }
        this.recordId = recordId;
        this.createdAt = System.currentTimeMillis();
        System.out.println("[DatabaseRecord Constructor] Initialized base id: " + recordId);
    }

    public abstract void validate();
}

class UserRecord extends DatabaseRecord {
    private String email;

    public UserRecord(String recordId, String email) {
        super(recordId); // Mandatory chaining to parent constructor
        this.email = email;
        System.out.println("[UserRecord Constructor] Initialized user email: " + email);
    }

    @Override
    public void validate() {
        System.out.println("Validating user record " + recordId + " with email " + email);
    }
}

public class RecordApp {
    public static void main(String[] args) {
        DatabaseRecord record = new UserRecord("REC-8801", "user@domain.com");
        record.validate();
    }
}

