abstract class BaseWidget {
    public BaseWidget() {
        System.out.println("1. BaseWidget constructor running");
        // DANGEROUS: Invoking overridden method inside constructor!
        render();
    }
    public abstract void render();
}

class ButtonWidget extends BaseWidget {
    // Field initialized with explicit value
    private String label = "CLICK_ME";

    public ButtonWidget() {
        super(); // Runs BaseWidget constructor first!
        System.out.println("3. ButtonWidget constructor running. label = " + label);
    }

    @Override
    public void render() {
        System.out.println("2. render() called! label is: " + label);
    }
}

public class WidgetDemo {
    public static void main(String[] args) {
        new ButtonWidget();
    }
}

