abstract class AuditEvent {
    protected final String eventId;
    protected final long timestamp;
    public AuditEvent(String eventId, long timestamp) {
        if (eventId == null) throw new IllegalArgumentException("eventId required");
        this.eventId = eventId;
        this.timestamp = timestamp;
    }
    public abstract String getDetails();
    public void log() {
        System.out.println("[Timestamp: " + timestamp + "] (" + eventId + ") " + getDetails());
    }
}

class UserLoginEvent extends AuditEvent {
    private String username;
    private String ipAddress;
    public UserLoginEvent(String eventId, long timestamp, String username, String ipAddress) {
        super(eventId, timestamp);
        this.username = username;
        this.ipAddress = ipAddress;
    }
    @Override
    public String getDetails() {
        return "User " + username + " logged in from " + ipAddress;
    }
}

public class AuditApp {
    public static void main(String[] args) {
        AuditEvent event = new UserLoginEvent("EVT-501", 1700000000L, "sarah", "192.168.1.1");
        event.log();
    }
}

abstract class VaultConfig {
    protected final String vaultId;
    protected final int securityLevel;
    public VaultConfig(String vaultId, int securityLevel) {
        if (securityLevel < 1 || securityLevel > 5) {
            throw new IllegalArgumentException("Invalid level");
        }
        this.vaultId = vaultId;
        this.securityLevel = securityLevel;
    }
    public void inspect() {
        System.out.println("Vault: " + vaultId + " | Security Tier: " + securityLevel);
    }
    public abstract boolean requiresBiometrics();
}

class HighSecurityVault extends VaultConfig {
    public HighSecurityVault(String vaultId) {
        super(vaultId, 5);
    }
    @Override
    public boolean requiresBiometrics() {
        return true;
    }
}

public class VaultApp {
    public static void main(String[] args) {
        VaultConfig vault = new HighSecurityVault("VAULT-ALPHA");
        vault.inspect();
        System.out.println("Biometrics required: " + vault.requiresBiometrics());
    }
}

