abstract class HardwareDevice {
    protected String serialNo;
    public HardwareDevice(String serialNo) {
        this.serialNo = serialNo;
        System.out.println("[1] Hardware initialized: " + serialNo);
    }
}

abstract class NetworkDevice extends HardwareDevice {
    protected String macAddress;
    public NetworkDevice(String serialNo, String macAddress) {
        super(serialNo);
        this.macAddress = macAddress;
        System.out.println("[2] Network NIC bound: " + macAddress);
    }
}

class SmartRouter extends NetworkDevice {
    private int antennaCount;
    public SmartRouter(String serialNo, String macAddress, int antennaCount) {
        super(serialNo, macAddress);
        this.antennaCount = antennaCount;
        System.out.println("[3] Router configured with " + antennaCount + " antennas");
    }
    public void boot() {
        System.out.println("Router " + serialNo + " (" + macAddress + ") ONLINE");
    }
}

public class RouterApp {
    public static void main(String[] args) {
        SmartRouter router = new SmartRouter("RT-909", "00:1B:44:11:3A:B7", 4);
        router.boot();
    }
}
